package com.buywise.modules.comparison.dto;

import com.buywise.modules.comparison.strategy.OfferScoreResult;
import com.buywise.modules.comparison.strategy.StrategyType;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/**
 * Deterministic mathematical summary of competing purchasing offers.
 * 
 * Strict Architecture Boundary: Computed entirely via deterministic backend arithmetic.
 * Never delegated to or generated by an LLM.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class DeterministicComparisonSummaryDto {

    private int offerCount;
    private String currency;
    private Long cheapestOfferId;
    private String cheapestOfferSeller;
    private BigDecimal lowestTotalPrice;

    private Long highestPriceOfferId;
    private String highestPriceOfferSeller;
    private BigDecimal highestTotalPrice;

    private BigDecimal absolutePriceDifference;
    private BigDecimal percentagePriceDifference;

    private Long bestWarrantyOfferId;
    private int longestWarrantyMonths;
    private int shortestWarrantyMonths;
    private int warrantyDifferenceMonths;

    private List<DeterministicOfferSummary> offerSummaries;
    private Map<StrategyType, List<OfferScoreResult>> rankingsByStrategy;
    private Map<String, Map<Long, String>> specificationComparisonMatrix;
}
